        "raw": "日本語等の学習支援",
        "start": 20548,
        "context": "が地域コミュニティの一員として\n自立し、共に安心・快適に暮らしていくた\n市民活\nめ、生活に最低限必要な日本語や日本社会に\n動推進 日本語等の学習支援\n関する学習及び日本人市民との交流の場であ\n課\nる市民ボランティアによる日本語教室の運営\nを支援します。\n\nＳＴＥＰ２\n戦略 多文化共生の\n活動の展開\n育2\n促",
