        "raw": "幹線道路等整備事業",
        "start": 67493,
        "context": "市総合都市交通計画を\n改定します。\n\n安全安心でかつ利便性の高いまちづくりの実\n道路整\n現を図るため、道路ネットワークの構築を目\n幹線道路等整備事業\n備課\n指し、幹線道路、地区幹線道路等を拡幅整備\nします。\n\n誰もが便利な移動手段強化プロジェクト\n\nＳＴＥＰ１\n戦略 公共交通の利\n公共交通の\n支4\n便性向上",
